mapper.select:
select s.id, s.name, s.no, s.gender, s.phone, s.degree, s.violation_count, s.violation_score, s.update_time, c.name as class_name from tlias.student as s inner join tlias.class as c on s.clazz_id = c.id
and s.name like concat('%',#{p.name},'%')
and s.degree <= #{p.degree}
and s.clazz_id = #{p.clazzId}
order by s.clazz_id asc

mapper.delete:
delete from tlias.student
where id in

    #{id}
